\"\"\"Minimal, standard-library-only client for OpenAI's Responses API.

This module lets you send private text prompts to the Responses API
(POST /v1/responses) using only the Python standard library.

Privacy notes:
- The API key is read from the environment (OPENAI_API_KEY) by default and is
  never logged or persisted to disk by this module.
- Prompts are sent only to OpenAI over HTTPS; nothing is written to files,
  printed, or otherwise disclosed unless you explicitly ask for it.
\"\"\"

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Iterator


DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_MODEL = \"gpt-4o-mini\"
DEFAULT_TIMEOUT = 60


class OpenAIError(Exception):
    \"\"\"Raised when the Responses API returns an error or the request fails.\"\"\"

    def __init__(self, message: str, status: int | None = None,
                 body: Any | None = None) -> None:
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    \"\"\"A tiny stdlib-only client for the OpenAI Responses API.\"\"\"

    def __init__(self, api_key: str | None = None, *,
                 base_url: str = DEFAULT_BASE_URL,
                 default_model: str = DEFAULT_MODEL,
                 timeout: float = DEFAULT_TIMEOUT) -> None:
        key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not key:
            raise OpenAIError(
                \"No API key provided. Set the OPENAI_API_KEY environment \"
                \"variable or pass api_key=...\"
            )
        self._api_key = key
        self.base_url = base_url.rstrip(\"/\")
        self.default_model = default_model
        self.timeout = timeout

    def _request(self, method: str, path: str, body: dict | None = None) -> Any:
        url = f\"{self.base_url}{path}\"
        data = json.dumps(body).encode(\"utf-8\") if body is not None else None
        headers = {
            \"Authorization\": f\"Bearer {self._api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"application/json\",
        }
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                raw = resp.read().decode(\"utf-8\")
        except urllib.error.HTTPError as exc:
            raise OpenAIError(
                f\"HTTP {exc.code} from {url}\",
                status=exc.code,
                body=_safe_json(exc.read().decode(\"utf-8\", \"replace\")),
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Request to {url} failed: {exc.reason}\") from exc

        if not raw:
            return {}
        try:
            return json.loads(raw)
        except json.JSONDecodeError as exc:
            raise OpenAIError(f\"Could not decode JSON response: {exc}\") from exc

    def responses_create(self, input: str | list[dict], *,
                          model: str | None = None,
                          instructions: str | None = None,
                          stream: bool = False,
                          **params: Any) -> Any:
        \"\"\"Create a response.

        Args:
            input: A private text prompt (string) or a list of input messages.
            model: Model to use; falls back to the client's default model.
            instructions: Optional system/developer instructions.
            stream: If True, iterate over Server-Sent Events instead.
            **params: Extra Responses API parameters (e.g. temperature).

        Returns:
            The parsed JSON response object (or an SSE iterator when streaming).
        \"\"\"
        payload: dict[str, Any] = {\"model\": model or self.default_model,
                                   \"input\": input}
        if instructions is not None:
            payload[\"instructions\"] = instructions
        payload.update(params)

        if stream:
            payload[\"stream\"] = True
            return self._stream(\"/responses\", payload)

        return self._request(\"POST\", \"/responses\", payload)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        \"\"\"Send a private text prompt and return the concatenated output text.\"\"\"
        response = self.responses_create(prompt, **kwargs)
        return extract_text(response)

    def _stream(self, path: str, body: dict) -> Iterator[dict]:
        url = f\"{self.base_url}{path}\"
        data = json.dumps(body).encode(\"utf-8\")
        headers = {
            \"Authorization\": f\"Bearer {self._api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"text/event-stream\",
        }
        req = urllib.request.Request(url, data=data, headers=headers, method=\"POST\")
        try:
            resp = urllib.request.urlopen(req, timeout=self.timeout)
        except urllib.error.HTTPError as exc:
            raise OpenAIError(
                f\"HTTP {exc.code} from {url}\",
                status=exc.code,
                body=_safe_json(exc.read().decode(\"utf-8\", \"replace\")),
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Request to {url} failed: {exc.reason}\") from exc

        with resp:
            for event, data in _iter_sse(resp):
                if data:
                    yield {\"event\": event, \"data\": _safe_json(data)}


def extract_text(response: dict) -> str:
    \"\"\"Concatenate all output_text chunks from a Responses API result.\"\"\"
    parts: list[str] = []
    for item in response.get(\"output\", []) or []:
        for content in item.get(\"content\", []) or []:
            if content.get(\"type\") == \"output_text\" and \"text\" in content:
                parts.append(content[\"text\"])
    return \"\".join(parts)


def _iter_sse(resp) -> Iterator[tuple[str, str]]:
    event, data_lines = \"\", []
    for line in resp:
        line = line.decode(\"utf-8\", \"replace\").rstrip(\"\\n\").rstrip(\"\\r\")
        if line == \"\":
            if data_lines:
                yield event, \"\\n\".join(data_lines)
            event, data_lines = \"\", []
            continue
        if line.startswith(\"event:\"):
            event = line[len(\"event:\"):].strip()
        elif line.startswith(\"data:\"):
            data_lines.append(line[len(\"data:\"):].strip())
    if data_lines:
        yield event, \"\\n\".join(data_lines)


def _safe_json(text: str) -> Any:
    try:
        return json.loads(text)
    except (json.JSONDecodeError, ValueError):
        return text


if __name__ == \"__main__\":
    import sys

    prompt = \" \".join(sys.argv[1:]) or \"Say hello in one sentence.\"
    client = OpenAIClient()
    try:
        print(client.ask(prompt))
    except OpenAIError as exc:
        print(f\"Error: {exc}\", file=sys.stderr)
        sys.exit(1)
